#!/usr/bin/env bash
# tools/fmm3d/run.sh: the FMM3D side of the comparison of Phase 6 T9 (C6.8;
# docs/design/optimisation.md §8.1). Our side is the sweep t9-fmm3d of
# tools/scaling/run.sh, on the same problems; README.md beside this file has the order
# and the commands per machine.
#
#     tools/fmm3d/run.sh <step> [<step> ...]
#
# Steps:
#   problems  writes the problem file of every distribution of DISTS and N of NS (the
#             workloads of tools/scaling/run.sh's t9 sweeps: points and 8 charge vectors
#             generated by index, the 1,000 sampled targets of the scaling harness's
#             errors and the f64 direct sum there) with `nd-fmm-bench --write-problem`,
#             into PROBLEMS; an existing file is kept
#   sweep     FMM3D's errors over the precisions of EPS_GRID: for every variant of
#             VARIANTS and every problem, one launch of the driver on every core
#             (OMP_NUM_THREADS=CORES), one vectorised call (8 densities) per eps, each
#             output measured by `nd-fmm-bench --check-output`; one file per variant and
#             problem, sweep-<variant>-<dist>-n<N>.txt; with SWEEP_VEC=0, eight calls of
#             one density each instead (FMM3D's default variant at N = 10^7: its
#             vectorised call keeps plane-wave expansions for every density in every box
#             and does not fit in a Kathleen node's 188 GB)
#   match     matched accuracy: for every variant, problem and p of PS, the eps of the
#             sweep whose relative L2 error of φ is closest (in its logarithm) to ours,
#             read from the summary lines of OURS (the t9-fmm3d output directory: the
#             launches with --errors 8, `batched`, mul_add=separate); the lines go to
#             MATCHED (default $OUT/matched.txt); light, so it also runs on a login node
#   time      FMM3D at the matched eps of MATCHED, each problem's eps in one launch per
#             thread count: on one thread (OMP_NUM_THREADS=1; T1_CALLS timed calls of one
#             density each, T1_LARGE_CALLS at N >= 10^7, after one untimed call; the
#             vectorised call with 8 densities too at N <= 10^6) and on every core (8 timed
#             calls, one per charge vector, after one untimed call; then the vectorised
#             call in a launch of its own per eps, so that one that runs out of memory
#             takes nothing else with it; every output measured by `nd-fmm-bench
#             --check-output`); files time-<variant>-<dist>-n<N>-t<threads>.txt and
#             time-<variant>-<dist>-n<N>-t<threads>-vec-eps<eps>.txt
#   crosscheck  the two codes' outputs against each other at every point, not only their
#             errors at the sampled targets: for every problem of DISTS and CROSS_NS
#             (default "100000 1000000"), ours at every p of PS (`nd-fmm-bench
#             --write-output`: Batched, one rank, CORES threads) and FMM3D at the matched
#             eps of MATCHED (8 calls of one density, the driver's FULL output), every
#             output checked against the direct sum at the sampled targets
#             (`--check-output`), then FMM3D's two builds at the eps matched to each p
#             against ours at that p (`--compare`); one file per problem,
#             crosscheck-<dist>-n<N>.txt; the full outputs (256 MB each at N = 10^6) are
#             removed at the end unless CROSS_KEEP is set
#
# Every launch's file starts with the command, the machine (CPU, the variant's
# build-info.txt) and, under Slurm, the job, or elsewhere the load before; macOS waits for
# a quiet machine first, as tools/scaling/run.sh does (QUIET). FMM3D runs with its defaults
# but OMP_NUM_THREADS: no binding variable is set (under Slurm the job binds the batch
# shell to the node's physical cores, tools/kathleen/jobs/lib.sh).
#
# Environment:
#   FMM3D_ROOT  where tools/fmm3d/build.sh installed FMM3D (as there: on Kathleen
#               $FMM_KATHLEEN_ROOT/fmm3d, on locust /data/ucahtbe/fmm3d, else required)
#   PROBLEMS    the problem files (default $FMM3D_ROOT/problems)
#   OUT         the output directory (default bench-results/fmm3d-<host>-<date>; on
#               Kathleen tools/kathleen/jobs/fmm3d.sbatch sets the root's logs/)
#   VARIANTS    FMM3D builds (default: those of "default fastker" that are built)
#   DISTS, NS, PS  the problems (default "cube plummer", "100000 1000000 10000000", "3 6
#               8 12": those of t9-fmm3d)
#   CORES       threads of the every-core runs (default 6 on macOS, the M6's Super and
#               Performance cores as in tools/scaling/run.sh; 40 under Slurm; 72 else)
#   EPS_GRID    the precisions of the sweep (default 1-2-5 per decade, 5e-1 ... 1e-10)
#   OURS, MATCHED, T1_CALLS (3), T1_LARGE_CALLS (1)  as above
#   SWEEP_VEC   1 (default): the sweep's errors from the vectorised call; 0: from eight
#               calls of one density
#   CALLS       timed single-density calls of `time` on every core (default 8, one per
#               charge vector, whose output is checked; fewer write no output, and the
#               errors come from the vectorised call); LARGE_CALLS (default CALLS) at
#               N >= 10^7
#   VEC_SKIP    "variant:N" pairs whose vectorised call `time` leaves out (default none;
#               the M3 Max's 64 GB and the M6's 24 GB: "default:10000000", the default
#               build's 8 densities at 10^7 ran out of 188 GB on Kathleen)
#   T1_MAX_N    the largest N of the one-thread launches of `time` (default: every N); the
#               M3 Max left out N = 10^7 at one thread (T1_MAX_N=1000000), as its
#               t9-fmm3d sweep does with ONLY; the M6 (24 GB) does the same
#   TIMEOUT     seconds per launch (default 7200)
#   QUIET       macOS only: the CPU percentage others may use before a launch (200)
#   DRY_RUN     if set, print the commands only

set -eu

root=$(CDPATH='' cd -- "$(dirname -- "$0")/../.." && pwd)
cd "$root"

if [ -z "${FMM3D_ROOT:-}" ]; then
    if [ -n "${FMM_KATHLEEN_ROOT:-}" ]; then
        FMM3D_ROOT=$FMM_KATHLEEN_ROOT/fmm3d
    elif [ -d /data/ucahtbe ]; then
        FMM3D_ROOT=/data/ucahtbe/fmm3d
    else
        echo "run.sh: set FMM3D_ROOT (tools/fmm3d/build.sh's)" >&2
        exit 2
    fi
fi
host=$(hostname -s 2>/dev/null || hostname)
OUT=${OUT:-bench-results/fmm3d-$host-$(date +%Y%m%d-%H%M)}
PROBLEMS=${PROBLEMS:-$FMM3D_ROOT/problems}
MATCHED=${MATCHED:-$OUT/matched.txt}
DISTS=${DISTS:-"cube plummer"}
NS=${NS:-"100000 1000000 10000000"}
PS=${PS:-"3 6 8 12"}
EPS_GRID=${EPS_GRID:-"5e-1 2e-1 1e-1 5e-2 2e-2 1e-2 5e-3 2e-3 1e-3 5e-4 2e-4 1e-4 5e-5 2e-5
1e-5 5e-6 2e-6 1e-6 5e-7 2e-7 1e-7 5e-8 2e-8 1e-8 5e-9 2e-9 1e-9 5e-10 2e-10 1e-10"}
T1_CALLS=${T1_CALLS:-3}
T1_LARGE_CALLS=${T1_LARGE_CALLS:-1}
T1_MAX_N=${T1_MAX_N:-}
CROSS_NS=${CROSS_NS:-"100000 1000000"}
SWEEP_VEC=${SWEEP_VEC:-1}
CALLS=${CALLS:-8}
LARGE_CALLS=${LARGE_CALLS:-$CALLS}
VEC_SKIP=${VEC_SKIP:-}
TIMEOUT=${TIMEOUT:-7200}
QUIET=${QUIET:-200}
case "$(uname -s)" in
Darwin) os=macos CORES=${CORES:-6} ;;
*)
    if [ -n "${SLURM_JOB_ID:-}" ]; then os=slurm CORES=${CORES:-40}; else os=linux CORES=${CORES:-72}; fi
    ;;
esac
if [ -z "${VARIANTS:-}" ]; then
    VARIANTS=
    for v in default fastker; do
        if [ -x "$FMM3D_ROOT/$v/bin/fmm3d_driver" ]; then VARIANTS="$VARIANTS $v"; fi
    done
fi
bench=${CARGO_TARGET_DIR:-target}/release/nd-fmm-bench
export OPENBLAS_NUM_THREADS=1 MKL_NUM_THREADS=1 BLIS_NUM_THREADS=1 GOTO_NUM_THREADS=1
export VECLIB_MAXIMUM_THREADS=1

if [ -z "${DRY_RUN:-}" ]; then
    mkdir -p "$OUT" "$PROBLEMS"
    cargo build --release -p nd-fmm-bench
fi

# timeout(1) is GNU's; macOS has it from Homebrew's coreutils, or not at all.
if command -v timeout >/dev/null 2>&1; then
    limit="timeout $TIMEOUT"
elif command -v gtimeout >/dev/null 2>&1; then
    limit="gtimeout $TIMEOUT"
else
    limit=
fi

# The problem file of <dist> <n>.
problem() { echo "$PROBLEMS/$1-n$2.bin"; }

# On macOS: wait until the processes other than this script's use at most QUIET% CPU.
quiet() {
    if [ "$os" != macos ]; then return 0; fi
    waited=0
    while :; do
        busy=$(ps -A -o pcpu=,comm= 2>/dev/null | awk '$2 !~ /fmm3d_driver|nd-fmm-bench/ { s += $1 }
            END { if (NR) printf "%d", s }')
        if [ -z "$busy" ]; then
            echo "the load is unknown (ps failed: a sandbox?); launched without waiting"
            return 0
        fi
        if [ "$busy" -le "$QUIET" ]; then break; fi
        if [ "$waited" -ge 3600 ]; then break; fi
        sleep 15
        waited=$((waited + 15))
    done
    echo "other processes at ${busy}% CPU when launched, after waiting ${waited} s"
}

# header <file> <variant> <command>: the file's first lines.
header() {
    {
        echo "# $(basename "$1" .txt)"
        echo
        echo "command: \`$3\`"
        echo
        if [ "$os" = macos ]; then
            echo "machine: $(sysctl -n machdep.cpu.brand_string 2>/dev/null || echo unknown)"
        else
            echo "machine: $(grep -m 1 'model name' /proc/cpuinfo | sed 's/.*: //')"
        fi
        echo
        echo '```text'
        cat "$FMM3D_ROOT/$2/build-info.txt" 2>/dev/null || echo "no build-info.txt for $2"
        echo '```'
        echo
        if [ "$os" = slurm ]; then
            echo "job $SLURM_JOB_ID (${SLURM_JOB_NAME:-}), QoS ${SLURM_JOB_QOS:-?}, node(s) \
${SLURM_JOB_NODELIST:-?}; launched $(date '+%Y-%m-%d %H:%M:%S'); nodes exclusive, batch \
shell bound to $(taskset -cp $$ 2>/dev/null | sed 's/.*: //')"
        else
            quiet
            echo "load before ($(date '+%Y-%m-%d %H:%M:%S')): $(uptime)"
        fi
        echo
    } >"$1"
}

# drive <file> <variant> <threads> <problem> <prefix> <eps list> <calls> <warmup> <vec>:
# one launch of the driver, its output appended to <file>, then the check of every
# output file it wrote.
drive() {
    file=$1 variant=$2 threads=$3 prob=$4 prefix=$5 eps=$6 calls=$7 warmup=$8 vec=$9
    driver=$FMM3D_ROOT/$variant/bin/fmm3d_driver
    command="OMP_NUM_THREADS=$threads $limit $driver $prob $prefix $eps $calls $warmup $vec"
    if [ -n "${DRY_RUN:-}" ]; then
        echo "$command"
        return
    fi
    echo "[$(date '+%H:%M:%S')] $(basename "$file" .txt): $command"
    header "$file" "$variant" "$command"
    status=0
    # shellcheck disable=SC2086 # $limit is a command and its argument, or empty
    OMP_NUM_THREADS=$threads $limit "$driver" "$prob" "$prefix" "$eps" "$calls" "$warmup" \
        "$vec" >>"$file" 2>&1 || status=$?
    if [ "$status" -ne 0 ]; then
        echo "FAILED (exit $status): $(basename "$file" .txt)" | tee -a "$file"
    fi
    outputs=$(grep -o -e ' out=[^ ]*' -e ' vec_out=[^ ]*' "$file" | sed 's/.*=//' | paste -sd, -)
    if [ -n "$outputs" ]; then
        "$bench" --check-output "$outputs" --problem "$prob" >>"$file" 2>&1 || true
    fi
    if [ "$os" != slurm ]; then
        echo "load after ($(date '+%Y-%m-%d %H:%M:%S')): $(uptime)" >>"$file"
    fi
}

# The sweep files' lines and ours, as one table: matched <variant> <dist> <n> <p> ...
match() {
    if [ -z "${OURS:-}" ] || [ ! -d "$OURS" ]; then
        echo "run.sh match: set OURS to the t9-fmm3d output directory of tools/scaling/run.sh" >&2
        exit 2
    fi
    grep -h '^summary:' "$OURS"/t9-fmm3d-*.txt | grep -e 'phi_l2=' | grep -e 'mul_add=separate' |
        awk '
        function field(line, key,    m) {
            if (match(line, " " key "=[^ ]*")) return substr(line, RSTART + length(key) + 2, RLENGTH - length(key) - 2)
            return ""
        }
        { print "ours", field($0, "dist"), field($0, "n"), field($0, "p"), field($0, "phi_l2"), field($0, "grad_l2"), field($0, "ranks") "x" field($0, "threads") }
    ' >"$OUT/ours.tmp"
    for f in "$OUT"/sweep-*.txt; do
        [ -e "$f" ] || continue
        base=$(basename "$f" .txt)
        rest=${base#sweep-}
        variant=${rest%%-*}
        rest=${rest#*-}
        dist=${rest%%-*}
        n=${rest#*-n}
        awk -v variant="$variant" -v dist="$dist" -v n="$n" '
            function field(line, key) {
                if (match(line, " " key "=[^ ]*")) return substr(line, RSTART + length(key) + 2, RLENGTH - length(key) - 2)
                return ""
            }
            /^fmm3d: eps=/ { e = field($0, "eps"); nterms[e] = field($0, "nterms"); ndiv[e] = field($0, "ndiv") }
            /^errors: file=/ {
                file = field($0, "file")
                sub(/\.vec\.out$/, "", file); sub(/\.out$/, "", file); sub(/.*-eps/, "", file)
                print "fmm3d", variant, dist, n, file, field($0, "phi_l2"), field($0, "grad_l2"), nterms[file], ndiv[file]
            }
        ' "$f"
    done >"$OUT/fmm3d.tmp"
    awk '
        FILENAME ~ /ours.tmp$/ { phi[$2 " " $3 " " $4] = $5; grad[$2 " " $3 " " $4] = $6; where[$2 " " $3 " " $4] = $7; next }
        { rows[++count] = $0 }
        END {
            for (key in phi) {
                split(key, k, " ")
                for (i = 1; i <= count; i++) {
                    split(rows[i], r, " ")
                    if (r[3] != k[1] || r[4] != k[2] || r[6] <= 0) continue
                    v = r[2]
                    d = log(r[6] / phi[key]); if (d < 0) d = -d
                    if (!((v " " key) in best) || d < best[v " " key]) { best[v " " key] = d; pick[v " " key] = rows[i] }
                }
            }
            for (vk in pick) {
                split(vk, k, " "); split(pick[vk], r, " ")
                key = k[2] " " k[3] " " k[4]
                printf "%s %s %s %s\tmatched: variant=%s dist=%s n=%s p=%s ours_phi_l2=%s ours_grad_l2=%s ours_split=%s eps=%s fmm3d_phi_l2=%s fmm3d_grad_l2=%s nterms=%s ndiv=%s\n", \
                    k[1], k[2], k[3], k[4], k[1], k[2], k[3], k[4], phi[key], grad[key], where[key], r[5], r[6], r[7], r[8], r[9]
            }
        }
    ' "$OUT/ours.tmp" "$OUT/fmm3d.tmp" | sort -k1,1 -k2,2 -k3,3n -k4,4n | cut -f 2 >"$MATCHED"
    rm -f "$OUT/ours.tmp" "$OUT/fmm3d.tmp"
    cat "$MATCHED"
}

for step in "$@"; do
    case "$step" in
    problems)
        for dist in $DISTS; do
            for n in $NS; do
                file=$(problem "$dist" "$n")
                if [ -f "$file" ]; then
                    echo "kept $file"
                    continue
                fi
                command="$bench --write-problem $file --dist $dist --n $n --vectors 8 --accuracy 1000 --threads $CORES"
                if [ -n "${DRY_RUN:-}" ]; then echo "$command"; continue; fi
                $command | tee -a "$OUT/problems.txt"
            done
        done
        ;;
    sweep)
        eps=$(echo $EPS_GRID | tr ' ' ',')
        for variant in $VARIANTS; do
            for dist in $DISTS; do
                for n in $NS; do
                    mkdir -p "$OUT/out"
                    if [ "$SWEEP_VEC" = 1 ]; then calls=0 vec=1; else calls=8 vec=0; fi
                    drive "$OUT/sweep-$variant-$dist-n$n.txt" "$variant" "$CORES" \
                        "$(problem "$dist" "$n")" "$OUT/out/sweep-$variant-$dist-n$n" "$eps" \
                        "$calls" 0 "$vec"
                done
            done
        done
        ;;
    match) match ;;
    time)
        if [ ! -f "$MATCHED" ]; then
            echo "run.sh time: no $MATCHED (run the match step, or set MATCHED)" >&2
            exit 2
        fi
        for variant in $VARIANTS; do
            for dist in $DISTS; do
                for n in $NS; do
                    eps=$(grep -e " variant=$variant dist=$dist n=$n " "$MATCHED" |
                        sed 's/.* eps=\([^ ]*\).*/\1/' | awk '!seen[$0]++' | paste -sd, -)
                    [ -n "$eps" ] || continue
                    calls=$T1_CALLS vec=1
                    if [ "$n" -ge 10000000 ]; then calls=$T1_LARGE_CALLS vec=0; fi
                    mkdir -p "$OUT/out"
                    if [ -z "$T1_MAX_N" ] || [ "$n" -le "$T1_MAX_N" ]; then
                        drive "$OUT/time-$variant-$dist-n$n-t1.txt" "$variant" 1 \
                            "$(problem "$dist" "$n")" "$OUT/out/time-$variant-$dist-n$n-t1" \
                            "$eps" "$calls" 1 "$vec"
                    fi
                    every=$CALLS
                    if [ "$n" -ge 10000000 ]; then every=$LARGE_CALLS; fi
                    drive "$OUT/time-$variant-$dist-n$n-t$CORES.txt" "$variant" "$CORES" \
                        "$(problem "$dist" "$n")" "$OUT/out/time-$variant-$dist-n$n-t$CORES" \
                        "$eps" "$every" 1 0
                    case " $VEC_SKIP " in *" $variant:$n "*) continue ;; esac
                    for e in $(echo "$eps" | tr ',' ' '); do
                        drive "$OUT/time-$variant-$dist-n$n-t$CORES-vec-eps$e.txt" "$variant" \
                            "$CORES" "$(problem "$dist" "$n")" \
                            "$OUT/out/time-$variant-$dist-n$n-t$CORES-vec" "$e" 0 0 1
                    done
                done
            done
        done
        ;;
    crosscheck)
        if [ ! -f "$MATCHED" ]; then
            echo "run.sh crosscheck: no $MATCHED (run the match step, or set MATCHED)" >&2
            exit 2
        fi
        mkdir -p "$OUT/cross"
        for dist in $DISTS; do
            for n in $CROSS_NS; do
                prob=$(problem "$dist" "$n")
                file=$OUT/crosscheck-$dist-n$n.txt
                pre=$OUT/cross/$dist-n$n
                if [ -n "${DRY_RUN:-}" ]; then
                    echo "crosscheck $dist $n: $prob"
                    continue
                fi
                header "$file" "${VARIANTS%% *}" "tools/fmm3d/run.sh crosscheck ($dist, N = $n)"
                for p in $PS; do
                    OMP_NUM_THREADS=1 $limit "$bench" --write-output "$pre-ours-p$p.full.out" \
                        --problem "$prob" --degree "$p" --threads "$CORES" >>"$file" 2>&1 ||
                        echo "FAILED: ours at p = $p" >>"$file"
                done
                for variant in $VARIANTS; do
                    eps=$(grep -e " variant=$variant dist=$dist n=$n " "$MATCHED" |
                        sed 's/.* eps=\([^ ]*\).*/\1/' | awk '!seen[$0]++' | paste -sd, -)
                    [ -n "$eps" ] || continue
                    OMP_NUM_THREADS=$CORES $limit "$FMM3D_ROOT/$variant/bin/fmm3d_driver" \
                        "$prob" "$pre-$variant" "$eps" 8 0 0 1 >>"$file" 2>&1 ||
                        echo "FAILED: FMM3D $variant" >>"$file"
                done
                outputs=$(ls "$pre"-*.full.out | paste -sd, -)
                "$bench" --check-output "$outputs" --problem "$prob" >>"$file" 2>&1 || true
                for p in $PS; do
                    others=
                    for variant in $VARIANTS; do
                        e=$(grep -e " variant=$variant dist=$dist n=$n p=$p " "$MATCHED" |
                            sed 's/.* eps=\([^ ]*\).*/\1/' | head -n 1)
                        [ -n "$e" ] && others="$others,$pre-$variant-eps$e.full.out"
                    done
                    [ -n "$others" ] || continue
                    "$bench" --compare "$pre-ours-p$p.full.out$others" >>"$file" 2>&1 || true
                done
                if [ -z "${CROSS_KEEP:-}" ]; then rm -f "$pre"-*.full.out; fi
                echo "[$(date '+%H:%M:%S')] $(basename "$file" .txt) done"
            done
        done
        ;;
    *)
        echo "run.sh: unknown step $step (problems, sweep, match, time or crosscheck)" >&2
        exit 2
        ;;
    esac
done
